(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.012-t*0.18)*12;
  const w1y = Math.cos(y*0.02-t*0.22)*18 + Math.sin(x*0.015+t*0.3)*12;
  const sx = x + w1x, sy = y + w1y;
  const w2x = Math.sin(sx*0.025-t*0.4)*8 + Math.cos(sy*0.02+t*0.35)*6;
  const w2y = Math.cos(sy*0.022+t*0.45)*8 + Math.sin(sx*0.018-t*0.3)*6;
  const fx = sx + w2x, fy = sy + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.85],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*110, 40+Math.cos(t*0.65+1)*60, 0.11, 2.1, 1.0],
    [400+Math.cos(t*0.55+2)*70, 200+Math.sin(t*0.75+4)*50, 0.085, 1.8, 1.1]
  ];
  let aS = 0, iS = 0, mS = 0, wt = 0;
  for (const [sX, sY, f, sp, w] of src) {
    const d = Math.sqrt((fx-sX)**2 + (fy-sY)**2);
    aS += Math.sin(d*f - t*sp) * w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * w;
    mS += Math.sin(d*f*1.3 - t*sp*0.8 + 3.0) * w;
    wt += w;
  }
  const act = aS/wt, inh = iS/wt, mod = mS/wt;
  const bg1 = Math.sin(fx*0.04+fy*0.025+t*0.8);
  const bg2 = Math.sin(fx*0.03-fy*0.04+t*1.1);
  const bg3 = Math.sin((fx+fy)*0.12+t*2.5)*0.2;
  const bg4 = Math.sin((fx-fy)*0.1-t*2)*0.2;
  const bg5 = Math.sin(fx*0.06*1.618+fy*0.06+t*1.7)*0.15;
  const bg = (bg1+bg2)/2 + bg3 + bg4 + bg5;
  const dist = Math.sqrt((fx-cx)**2 + (fy-cy)**2);
  const ang = Math.atan2(fy-cy, fx-cx);
  const sp1 = Math.sin(dist*0.05-ang*3-t*1.5);
  const sp2 = Math.sin(dist*0.04+ang*4-t*1.2);
  const sp3 = Math.sin(dist*0.07-ang*2+t*0.9)*0.3;
  const spiral = (sp1+sp2)*0.4 + sp3;
  const micro = Math.sin(fx*0.3+t*3)*Math.sin(fy*0.3-t*2.5)*0.12;
  const rd1 = act - inh*0.65 + bg*0.25 + spiral*0.35;
  const rd2 = mod*0.5 - act*inh*0.3 + spiral*0.2;
  const reaction = Math.tanh((rd1 + rd2)*2.0);
  const cell = Math.tanh((Math.sin(fx*0.15)*Math.sin(fy*0.15) + Math.sin((fx+fy)*0.1+t)*0.5)*1.5)*0.25;
  const edge = 1.0 - Math.pow(1.0 - Math.abs(reaction), 3)*0.4;
  const glow = Math.pow(Math.max(0, reaction), 2)*0.5;
  const vign = 1.0 - Math.pow(dist/300, 2)*0.3;
  const blend = (reaction*0.65 + cell*0.15 + glow*0.2) * edge * vign + micro;
  const v = Math.max(0, Math.min(1, blend*0.5+0.5));
  const pal = [
    [5,10,45],[10,35,80],[12,65,105],[18,110,130],
    [45,155,145],[120,190,130],[210,195,80],[235,150,60],
    [220,90,55],[185,50,70],[130,25,65],[65,15,55],[5,10,45]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.85 + Math.sin(reaction*Math.PI)*0.15 + glow*0.3;
  const hi = Math.max(0, reaction-0.5)*0.6;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum + hi*60)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum + hi*30)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum + hi*20)|0)
  ];
}
